# Reconciliation review

A review passes only when:

- both source totals agree to the reported matched and unmatched populations;
- every row is accounted for exactly once;
- the key, tolerance, date basis, sign convention, and currency are explicit;
- duplicates and missing identifiers are surfaced;
- material breaks have evidence-backed causes, owners, and actions;
- old reconciling items are aged under the engagement policy;
- preparer and reviewer are different identities;
- the review binds to the exact evidence and result digests.

An approval label without the checks and evidence is not a review.

#!/usr/bin/env python3
"""
atomic_fetch.py — Single execute_code call that replaces 3 sequential tool calls.

Replaces:
  - skill_view(finny-claude-tools-skill)        → envelope rules injected as summary
  - hindsight_recall(query)                      → context from Hindsight cloud
  - skill_view(netsuite-suiteql) / resolver.md  → account IDs, status codes, JOIN patterns

Usage inside execute_code:
Use `mcp__finny_fixture__query` with the local resolver; atomic_fetch.py is disabled in golden-eval staging.
  # Returns JSON: {intent, resolver_hits, hindsight_context, envelope_rules, ready_to_execute}

Output: structured JSON to stdout
Error: non-zero exit + message to stderr (never crashes silently)
"""

import sys
import os
import json
import subprocess
import re
import shutil
import concurrent.futures

# ── 0. Guard: safe to import as module ────────────────────────────────────────
# All primitives (catalog, rules, schema, hindsight) are defined at module level
# and importable. CLI execution is in main(); call main(query) or run as script.

# === Phase 1: rules primitive (Task 1.3) ===
import yaml as _yaml
from types import SimpleNamespace as _NS
from pathlib import Path as _Path

_REFS_DIR = _Path(__file__).resolve().parent.parent / "references"


def _load_universal_rules():
    return _yaml.safe_load((_REFS_DIR / "universal-rules.yaml").read_text())


def _rules_lookup(domain):
    data = _load_universal_rules().get("keyword_sections") or {}
    return data.get(domain)


def _rules_gl_accounts(category):
    entry = _rules_lookup(category) or {}
    return list(entry.get("gl_accounts", []))


rules = _NS(lookup=_rules_lookup, gl_accounts=_rules_gl_accounts)

# === Phase 1: catalog primitive (Task 1.4) ===
_RESOLVER_PATH = _REFS_DIR / "resolver.md"
_FINANCE_ROUTES_PATH = _REFS_DIR / "finance-routes.yaml"


def _resolver_path():
    return _RESOLVER_PATH


def _parse_resolver_blocks():
    """Parse INTENT blocks from resolver.md → [(intent_id, body), ...]

    intent_id is the bare token after INTENT:.
    body is the metadata INSIDE the comment (triggers, known_field, etc.) —
    i.e. everything between the intent id and the closing --> of that comment.
    """
    text = _resolver_path().read_text()
    pattern = re.compile(
        r"<!--\s*INTENT:\s*(\w+)(.*?)-->",
        re.DOTALL,
    )
    return [(m.group(1).strip(), m.group(2).strip()) for m in pattern.finditer(text)]


def _catalog_search(query, top_k=5):
    q_words = set(re.findall(r"\w+", query.lower()))
    if not q_words:
        return []
    scored = []
    for intent_id, body in _parse_resolver_blocks():
        body_words = set(re.findall(r"\w+", body.lower()))
        score = len(q_words & body_words)
        if score > 0:
            excerpt = body[:800]
            scored.append({"intent": intent_id, "score": score, "excerpt": excerpt})
    scored.sort(key=lambda x: -x["score"])
    return scored[:top_k]


def _catalog_get_block(intent_id):
    for iid, body in _parse_resolver_blocks():
        if iid == intent_id:
            return body
    return None


catalog = _NS(search=_catalog_search, get_block=_catalog_get_block)


def _normalized_words(value):
    return tuple(re.findall(r"[a-z0-9]+", value.casefold()))


def _contains_phrase(words, phrase):
    needle = _normalized_words(phrase)
    return bool(needle) and any(words[index:index + len(needle)] == needle for index in range(len(words) - len(needle) + 1))


def _population_readiness(query):
    routes = _yaml.safe_load(_FINANCE_ROUTES_PATH.read_text()) or {}
    words = _normalized_words(query)
    matches = [
        (item, alias)
        for item in routes.get("workflows") or []
        for alias in item.get("aliases") or []
        if _contains_phrase(words, str(alias))
    ]
    matches.sort(key=lambda match: len(_normalized_words(match[1])), reverse=True)
    workflow = matches[0][0] if matches else None
    if workflow is None:
        return [], [], None
    populations = []
    unresolved = []
    for population in workflow.get("populations") or []:
        missing_assets = []
        for asset in population.get("required_assets") or []:
            skill = str(asset.get("skill") or "").strip()
            file = str(asset.get("file") or "").strip()
            if not skill or not file:
                missing_assets.append({"skill": skill, "file": file})
        status = "resolved" if not missing_assets else "blocked"
        populations.append({"id": population["id"], "status": status, "missing_assets": missing_assets})
        if missing_assets:
            unresolved.append(
                {
                    "population": population["id"],
                    "reason": "incomplete_required_asset_route",
                    "missing_assets": missing_assets,
                }
            )
    return populations, unresolved, workflow

# === Phase 1: schema primitive (Task 1.5) ===
_SCHEMA_YAML_PATH = _REFS_DIR / "sharechat-schema.yaml"


def _load_schema_yaml():
    return _yaml.safe_load(_SCHEMA_YAML_PATH.read_text())


def _schema_describe(record_type):
    """Return {record_type, fields: [{name, type, ...}, ...], joins: []} for a record type."""
    schema_data = _load_schema_yaml()

    # Extract all fields that apply to this record_type
    # Note: tables dict uses high-level names (transaction, vendor) while field
    # record_types use specific types (vendorBill, purchaseOrder). We check fields only.
    all_fields = schema_data.get("fields") or {}
    applicable_fields = []

    for field_name, field_meta in all_fields.items():
        if not isinstance(field_meta, dict):
            continue
        record_types = field_meta.get("record_types") or []
        if record_type in record_types:
            # Build field entry with name + all metadata
            field_entry = {"name": field_name}
            field_entry.update(field_meta)
            applicable_fields.append(field_entry)

    # Return None if no fields found for this record type
    if not applicable_fields:
        return None

    return {
        "record_type": record_type,
        "fields": applicable_fields,
        "joins": [],  # No joins in this YAML
    }


def _schema_fields(record_type):
    """Return list of field dicts for a record type."""
    info = _schema_describe(record_type)
    return info["fields"] if info else []


def _schema_joins(record_type):
    """Return list of join dicts for a record type."""
    info = _schema_describe(record_type)
    return info["joins"] if info else []


schema = _NS(describe=_schema_describe, fields=_schema_fields, joins=_schema_joins)


# === Hindsight primitive ===
def _hindsight_config_path():
    configured = os.environ.get("HINDSIGHT_CONFIG", "").strip()
    return _Path(configured).expanduser() if configured else _REFS_DIR / "hindsight-config.json"


def _load_hindsight_config():
    path = _hindsight_config_path()
    try:
        data = json.loads(path.read_text())
    except FileNotFoundError:
        return {}
    except (json.JSONDecodeError, OSError) as exc:
        raise RuntimeError(f"Could not read Hindsight config at {path}: {exc}") from exc
    if not isinstance(data, dict):
        raise RuntimeError(f"Hindsight config at {path} must contain a JSON object")
    return data


def _resolve_bank_ids(config=None):
    """Resolve enabled Hindsight banks from explicit configuration."""
    hcfg = _load_hindsight_config() if config is None else config
    banks_cfg = hcfg.get("banks") or {}
    bank_ids = []
    if isinstance(banks_cfg, dict):
        bank_ids = [
            str(bank_id).strip()
            for bank_id, bank_cfg in banks_cfg.items()
            if str(bank_id).strip()
            and isinstance(bank_cfg, dict)
            and bank_cfg.get("enabled", True)
        ]

    if not bank_ids:
        legacy_bank = str(hcfg.get("bank_id") or "").strip()
        if legacy_bank:
            bank_ids = [legacy_bank]

    if not bank_ids:
        bank_ids = [
            value.strip()
            for value in os.environ.get("HINDSIGHT_BANK_IDS", "").split(",")
            if value.strip()
        ]

    if not bank_ids:
        single_bank = os.environ.get("HINDSIGHT_BANK_ID", "").strip()
        if single_bank:
            bank_ids = [single_bank]

    if not bank_ids:
        raise RuntimeError(
            "No Hindsight bank IDs configured in "
            f"{_hindsight_config_path()} or HINDSIGHT_BANK_IDS/HINDSIGHT_BANK_ID"
        )
    return list(dict.fromkeys(bank_ids))


def _resolve_python():
    """Return an available Python interpreter without host-specific paths."""
    if sys.executable and os.path.isfile(sys.executable) and os.access(sys.executable, os.X_OK):
        return sys.executable
    python = shutil.which("python3") or shutil.which("python")
    if python:
        return python
    raise RuntimeError("No Python interpreter is available for Hindsight recall")


def _recall_one_bank(query, bank_id, config, budget, max_tokens):
    api_key = str(config.get("apiKey") or "").strip()
    if not api_key:
        return None, f"No apiKey in {_hindsight_config_path()}"

    api_url = config.get("api_url") or "http://127.0.0.1:1/disabled-external-hindsight"
    code = f"""
import json
import warnings
warnings.filterwarnings('ignore')
import hindsight_client as hc
try:
    client = hc.Hindsight(base_url={json.dumps(api_url)}, api_key={json.dumps(api_key)})
    result = client.recall(
        bank_id={json.dumps(bank_id)},
        query={json.dumps(query)},
        budget={json.dumps(budget)},
        max_tokens={int(max_tokens)},
    )
    items = [getattr(item, 'text', str(item)) for item in (result.results or [])]
    print(json.dumps(items))
except Exception as exc:
    raise SystemExit(str(exc))
"""
    try:
        proc = subprocess.run(
            [_resolve_python(), "-c", code],
            capture_output=True,
            text=True,
            timeout=15,
        )
    except Exception as exc:
        return None, str(exc)[:300]

    if proc.returncode != 0:
        return None, (proc.stderr or proc.stdout or "empty output")[:300]
    try:
        return json.loads(proc.stdout.strip()), ""
    except json.JSONDecodeError as exc:
        return None, f"json parse error: {exc}"


def _hindsight_recall(query, budget="mid", max_tokens=3000, bank_ids=None, bank_id=None):
    """Recall context from one or more configured banks with per-bank errors."""
    config = _load_hindsight_config()
    if bank_ids is not None:
        resolved_bank_ids = [str(value).strip() for value in bank_ids if str(value).strip()]
    elif bank_id is not None:
        resolved_bank_ids = [str(bank_id).strip()] if str(bank_id).strip() else []
    else:
        try:
            resolved_bank_ids = _resolve_bank_ids(config)
        except RuntimeError as exc:
            return {"banks": {}, "errors": [("config", str(exc))]}

    resolved_bank_ids = list(dict.fromkeys(resolved_bank_ids))
    if not resolved_bank_ids:
        return {"banks": {}, "errors": [("config", "No Hindsight bank IDs supplied")]}

    banks = {}
    errors = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(resolved_bank_ids)) as executor:
        pending = {
            executor.submit(
                _recall_one_bank,
                query,
                current_bank_id,
                config,
                budget,
                max_tokens,
            ): current_bank_id
            for current_bank_id in resolved_bank_ids
        }
        for future in concurrent.futures.as_completed(pending):
            current_bank_id = pending[future]
            try:
                result, error = future.result()
            except Exception as exc:
                result, error = None, str(exc)[:300]
            if error:
                errors.append((current_bank_id, error))
            else:
                banks[current_bank_id] = result

    return {"banks": banks, "errors": errors}


hindsight = _NS(recall=_hindsight_recall)


# ── 1–5: CLI execution — wrapped in main() so import path stays clean ────────
def main(query):
    """Run atomic_fetch for a given query string and print JSON to stdout."""
    # ── 1. Resolver hits ────────────────────────────────────────────────────
    resolver_hits = []
    sections = []
    resolver_raw = ""

    try:
        resolver_raw = _resolver_path().read_text()
    except FileNotFoundError:
        pass

    query_words = set(re.findall(r"\w+", query.lower()))
    for hit in catalog.search(query, top_k=5):
        hit_words = set(re.findall(r"\w+", hit["excerpt"].lower()))
        resolver_hits.append({
            "intent": hit["intent"],
            "match_words": sorted(query_words & hit_words),
            "content": hit["excerpt"],
        })

    try:
        all_blocks = _parse_resolver_blocks()
        sections = [intent for intent, _ in all_blocks]
    except Exception:
        sections = []

    # ── 2. Hindsight recall — configured-bank fan-out ──────────────────────
    # Uses the same generic primitive exposed to skills and tools.
    hindsight_context = ""
    hindsight_error = ""
    try:
        recalled = hindsight.recall(query, budget="mid", max_tokens=1500)
        context_items = []
        for bank_result in recalled["banks"].values():
            if isinstance(bank_result, list):
                context_items.extend(str(item)[:600] for item in bank_result)
            elif bank_result is not None:
                context_items.append(str(bank_result)[:600])
        hindsight_context = "\n\n---\n\n".join(context_items)
        if recalled["errors"] and all(
            message.startswith("No apiKey") for _, message in recalled["errors"]
        ):
            hindsight_error = "No apiKey or no enabled banks in hindsight config"
        else:
            hindsight_error = "; ".join(
                f"{bank}: {message}" for bank, message in recalled["errors"]
            )
    except Exception as e:
        hindsight_error = str(e)[:300]

    # ── 3. Intent classification — dynamic from resolver.md triggers ────────
    # Parses <!-- INTENT: <id>  triggers: <kw1>, <kw2>, ... --> blocks directly.
    # No hardcoded intent list — every intent added to resolver.md is auto-detected.
    detected_intents = []
    query_words = _normalized_words(query)

    def _detect_intents_from_resolver():
        """
        Extract intent_id → [trigger phrases] from resolver.md comment headers.
        Falls back to universal-rules.yaml keyword_sections for legacy intents
        (tds, gst, payroll_gl, etc.) that don't have INTENT blocks in resolver.md.
        Returns list of matched intent IDs.
        """
        matched = []
        seen = set()

        # Primary: parse triggers from resolver.md INTENT blocks
        try:
            resolver_text = _resolver_path().read_text()
            # Match: <!-- INTENT: <id> ... triggers: <phrase1>, <phrase2> ... -->
            header_pattern = re.compile(
                r"<!--\s*INTENT:\s*(\w+)(.*?)-->",
                re.DOTALL
            )
            trigger_line_pattern = re.compile(
                r"triggers:\s*(.+)"
            )
            for m in header_pattern.finditer(resolver_text):
                intent_id = m.group(1).strip()
                header_body = m.group(2)
                tl = trigger_line_pattern.search(header_body)
                if not tl:
                    continue
                triggers = [t.strip() for t in tl.group(1).split(",") if t.strip()]
                for trigger in triggers:
                    if _contains_phrase(query_words, trigger):
                        if intent_id not in seen:
                            matched.append(intent_id)
                            seen.add(intent_id)
                        break
        except Exception:
            pass

        # Fallback: universal-rules.yaml keyword_sections (legacy intents without
        # INTENT blocks in resolver.md — e.g. tds, gst, vendor_lookup, ap_aging)
        try:
            yaml_sections = _load_universal_rules().get("keyword_sections") or {}
            for section, entry in yaml_sections.items():
                if section in seen:
                    continue  # already matched via resolver.md
                keywords = list((entry or {}).get("keywords", [])) + list((entry or {}).get("gl_accounts", []))
                if any(_contains_phrase(query_words, str(kw)) for kw in keywords):
                    matched.append(section)
                    seen.add(section)
        except Exception:
            pass

        return matched

    detected_intents = _detect_intents_from_resolver()
    populations, unresolved_items, matched_workflow = _population_readiness(query)
    if matched_workflow and matched_workflow["id"] not in detected_intents:
        detected_intents.insert(0, matched_workflow["id"])

    # ── 3a. Runbook routing — intent → registered executable pipeline ───────
    # The agent must NOT have a hardcoded script name in its prompt. It asks
    # atomic_fetch which runbook serves the detected intents and follows that.
    def _match_runbook(intents):
        try:
            import datetime as _dt
            import yaml as _yaml
        except Exception:
            return None, "pyyaml unavailable"
        path = _resolver_path().parent / "runbooks.yaml"
        if not path.exists():
            return None, "runbooks.yaml not found"
        try:
            registry = _yaml.safe_load(path.read_text()) or {}
        except Exception as exc:
            return None, f"runbooks.yaml parse error: {exc}"
        best, best_score = None, 0
        for rb in registry.get("runbooks") or []:
            score = len(set(rb.get("intents") or []) & set(intents))
            if score > best_score:
                best, best_score = rb, score
        if best is None:
            return None, "no runbook registered for these intents"

        # Resolve period slots from the query text so the commands are runnable.
        slots = {}
        months = ("january february march april may june july august september "
                  "october november december").split()
        found = []
        for m in re.finditer(
            r"(\d{1,2})(?:st|nd|rd|th)?(?:\s+|-)([A-Za-z]+)(?:\s+|-)(\d{4})", query, re.I
        ):
            day, mon, year = m.group(1), m.group(2).lower(), m.group(3)
            mon = next((i + 1 for i, name in enumerate(months)
                        if name.startswith(mon[:3])), None)
            if mon:
                found.append(f"{year}-{mon:02d}-{int(day):02d}")
        for m in re.finditer(r"\b(\d{4}-\d{2}-\d{2})\b", query):
            found.append(m.group(1))
        if len(found) >= 3:
            slots["receipt_start"], slots["receipt_end"], slots["as_of"] = found[:3]
        elif len(found) == 2:
            slots["receipt_start"], slots["receipt_end"] = found
            slots["as_of"] = found[1]
        elif len(found) == 1:
            slots["as_of"] = found[0]
        if slots.get("as_of"):
            slots["as_of_compact"] = slots["as_of"].replace("-", "")
        slots.update(best.get("scope_defaults") or {})

        def _slot(pattern, flags=re.I):
            match = re.search(pattern, query, flags)
            return match.group(1).strip(" .,;") if match else None

        scope_slots = {
            "entity": _slot(r"\b(?:legal\s+entity|entity(?:\s+scope)?)\s*(?:=|:|is)?\s+([A-Za-z0-9][A-Za-z0-9._-]*)"),
            "subsidiary_scope": _slot(r"\bsubsidiary(?:\s+scope)?\s*(?:=|:|is)?\s+([A-Za-z0-9][A-Za-z0-9._-]*)"),
            "currency_basis": _slot(r"\bcurrency(?:\s+basis)?\s*(?:=|:|is)?\s+([A-Z]{3})", 0),
            "accounting_book": _slot(r"\baccounting\s+book\s*(?:=|:|is)?\s+([A-Za-z0-9][A-Za-z0-9._-]*)"),
            "comparison_basis": "none" if re.search(r"\bno\s+comparison\b", query, re.I) else _slot(
                r"\bcomparison(?:\s+basis)?\s*(?:=|:|is)?\s+([A-Za-z0-9][A-Za-z0-9._-]*)"
            ),
            "reporting_timezone": _slot(
                r"\b(?:reporting\s+)?timezone\s*(?:=|:|is)?\s+([A-Za-z_]+(?:/[A-Za-z_]+)?)"
            ),
        }
        if not scope_slots["subsidiary_scope"] and re.search(r"\bconsolidated\b", query, re.I):
            scope_slots["subsidiary_scope"] = "consolidated"
        slots.update({key: value for key, value in scope_slots.items() if value})

        missing = [s for s in (best.get("requires_slots") or []) if s not in slots]
        resolved = dict(best)
        for key in ("batch_command", "build_command", "emits"):
            value = best.get(key)
            if isinstance(value, str) and not missing:
                try:
                    resolved[key] = " ".join(value.format(**slots).split())
                except KeyError:
                    pass
        resolved["resolved_slots"] = slots
        resolved["missing_slots"] = missing
        return resolved, None

    recommended_runbook, runbook_error = _match_runbook(detected_intents)
    if recommended_runbook and recommended_runbook.get("missing_slots"):
        unresolved_items.append(
            {"reason": "missing_required_scope", "slots": recommended_runbook["missing_slots"]}
        )

    # ── 3b. Schema.db probe — runs when schema_field_lookup intent detected
    #        OR when query contains field-discovery keywords ──────────────────
    SCHEMA_FIELD_KEYWORDS = {
        "field", "schema", "custentity", "custbody", "column", "table",
        "which field", "what field", "field name", "field for", "field on",
        "ns field", "netsuite field", "custom field", "entity field",
        "find field", "locate field", "does field", "field exist",
    }
    _qwords = set(re.findall(r"\w+", query.lower()))
    _schema_trigger = (
        "schema_field_lookup" in detected_intents
        or bool(_qwords & {"field", "schema", "custentity", "custbody", "column"})
    )

    schema_db_hits = []
    schema_db_error = ""

    if _schema_trigger:
        try:
            import sqlite3 as _sqlite3
            _db_path = str(_Path(__file__).resolve().parent.parent / "repo" / "data" / "netsuite_schema.db")
            # Extract keywords from query — strip common stop words
            _stop = {"the", "a", "an", "is", "in", "on", "for", "what", "which",
                     "how", "to", "do", "we", "use", "get", "our", "this", "that",
                     "and", "or", "not", "with", "from", "of", "at", "by", "it"}
            _kws = [w for w in _qwords if len(w) > 2 and w not in _stop]
            _conn = _sqlite3.connect(_db_path)
            _conn.row_factory = _sqlite3.Row
            _all_hits = []
            _seen_names = set()
            for _kw in _kws:
                _cur = _conn.execute(
                    """SELECT record_type, name, display_name, field_type
                       FROM fields
                       WHERE LOWER(name) LIKE ? OR LOWER(display_name) LIKE ?
                       ORDER BY record_type, name
                       LIMIT 20""",
                    (f"%{_kw}%", f"%{_kw}%")
                )
                for _row in _cur.fetchall():
                    _key = (_row["record_type"], _row["name"])
                    if _key not in _seen_names:
                        _seen_names.add(_key)
                        _all_hits.append({
                            "record_type": _row["record_type"],
                            "name": _row["name"],
                            "display_name": _row["display_name"] or "",
                            "field_type": _row["field_type"] or "",
                            "matched_keyword": _kw,
                        })
            _conn.close()
            # Sort: vendor fields first, then by record_type, then name
            _all_hits.sort(key=lambda r: (0 if r["record_type"] == "vendor" else 1, r["record_type"], r["name"]))
            schema_db_hits = _all_hits[:30]
        except Exception as _e:
            schema_db_error = str(_e)[:300]

    # ── 4. Envelope rules summary ───────────────────────────────────────────
    ENVELOPE_RULES_SUMMARY = {
        "status_values": ["ok", "partial", "running", "refused", "error", "needs_input"],
        "required_fields": ["intent_restated", "status", "env_used", "sources[].rows_scanned"],
        "error_required_when": "status is 'refused' or 'error' → error.retryable (bool) is REQUIRED",
        "rows_scanned_rule": "0 for skill/memory lookups, actual int for SuiteQL/REST. Never null.",
        "data_rows_format": "array of arrays, NOT array of objects",
        "error_codes": ["entity_not_found", "period_invalid", "permission_denied", "upstream_timeout", "schema_drift", "other"],
        "refused_not_error": "Out-of-scope → status='refused', NOT status='error' with OUT_OF_SCOPE code",
        "no_preamble": "No greetings. No 'Based on what I found…'. Envelopes only.",
        "sign_convention": "Apply ShareChat sign conventions ONCE. Bridge does not re-sign.",
