#!/usr/bin/env python3
"""
ShareChat AR Collection Status Tracker — Persistent Carry-Forward Pipeline (Solution 1)

Automates the weekly AR Collection Report per Latha U's specifications:
1. Categorizes Weekly Receipts into 3 distinct operational streams:
   - Domestic Ad Receipts (NetSuite Posted CustPymt)
   - Direct Bank Receipts (Unposted Bank Statement feeds)
   - International Ad Revenue (Foreign Inward Remittance / TT)
2. Merges NetSuite live open ad invoices with pending/legacy invoices (Pending Invoices.xlsx / Input Sheet B),
   ensuring complete deduplication.
3. Recomputes DPD and standard 9-bracket aging schedule as of the cutoff date.
4. Produces the 4-tab workbook: 'Summary', 'Receipts for the Week', 'Open Invoices as of [Date]', 'NetSuite Field Gap Analysis'.
"""

import sys, os, datetime, argparse, re
from decimal import Decimal, ROUND_HALF_UP

sys.path.insert(0, os.path.expanduser('~/.finny/skills/netsuite-suiteql/repo'))
try:
    from netsuite_kb.client import suiteql
except ImportError:
    suiteql = None

EXCLUDE_AR_ACCTS = {'1285', '473', '471', '469'}
EXCLUDE_INV_PREFIXES = ('MTFA', 'SCUK', 'SCSG', 'MAPL', 'MIPL')
EXCLUDE_INV_NOS = {'MT2526000597', 'MT2526000598'}
EXCLUDE_MEMO_CONTAINS = (
    'Invoice for Asset Disposal',
    'Consolidation of Disposed Assets',
    'Laptop sale',
)
EXCLUDE_ENTITIES = {'100893', 'C100893'}
EXCLUDE_ENTITY_NAMES = {'customer others - laptop sale'}
TRADE_DEBTOR_GLS = {'111001', '112001'}
INTERCOMPANY_PREFIXES = ('SCUK', 'SCSG', 'MAPL', 'MIPL')
LAPTOP_SALE_PREFIXES = ('MTFA',)
ALLOWED_MOVEMENT_TYPES = {'application', 'credit', 'payment'}


class ARContractError(ValueError):
    """Raised when an input attempts to bypass the deterministic AR contract."""


class SAPCarryForwardMissingError(ARContractError):
    """Raised when the mandatory signed SAP carry-forward input is absent."""


class NetSuiteSnapshotMissingError(ARContractError):
    """Raised when the frozen NetSuite source snapshot is not identified."""


def _as_date(value, field_name):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        try:
            return datetime.date.fromisoformat(value)
        except ValueError as exc:
            raise ARContractError(
                f"{field_name} must be an ISO date (YYYY-MM-DD): {value!r}"
            ) from exc
    raise ARContractError(f"{field_name} is required and must be a date")


def _as_decimal(value, field_name):
    try:
        return Decimal(str(value))
    except Exception as exc:
        raise ARContractError(f"{field_name} must be numeric: {value!r}") from exc


def _normalize_original_amount_inr(row):
    """Return transaction amount and its explicit INR reporting value."""
    transaction_amount = _as_decimal(
        row.get('original_amount'), 'original_amount'
    )
    currency = str(row.get('currency') or 'INR').strip().upper()
    if row.get('original_amount_inr') is not None:
        inr_amount = _as_decimal(
            row.get('original_amount_inr'), 'original_amount_inr'
        )
        fx_rate = (
            _as_decimal(row.get('fx_rate'), 'fx_rate')
            if row.get('fx_rate') is not None
            else Decimal('1.00') if currency == 'INR' else None
        )
    elif currency == 'INR':
        fx_rate = Decimal('1.00')
        inr_amount = transaction_amount
    else:
        if row.get('fx_rate') is None:
            raise ARContractError(
                f"fx_rate is required for foreign currency {currency}"
            )
        fx_rate = _as_decimal(row.get('fx_rate'), 'fx_rate')
        if fx_rate <= 0:
            raise ARContractError('fx_rate must be positive')
        inr_amount = (transaction_amount * fx_rate).quantize(
            Decimal('0.01'), rounding=ROUND_HALF_UP
        )
    return transaction_amount, inr_amount, currency, fx_rate


def normalize_finance_reference(value):
    """Return the cross-source key used to match native and legacy invoices."""
    normalized = re.sub(r'[^A-Z0-9]', '', str(value or '').upper())
    if not normalized:
        raise ARContractError("invoice finance reference is required")
    return normalized


def _invoice_reference(row):
    return row.get('invoice_no') or row.get('reference_key') or row.get('invoice_ref')


def _posted(value):
    if isinstance(value, bool):
        return value
    return str(value or '').strip().upper() in {'T', 'TRUE', 'Y', 'YES', '1'}


def _classification_reason(row):
    gl_account = str(row.get('gl_account') or row.get('account_number') or '').strip()
    invoice_no = normalize_finance_reference(_invoice_reference(row))
    memo = str(row.get('memo') or '')
    entity_id = str(row.get('entity_id') or '').strip()
    entity_name = str(row.get('entity_name') or '').strip().casefold()

    if gl_account not in TRADE_DEBTOR_GLS:
        return 'non_trade_debtor_gl'
    if not _posted(row.get('posted')):
        return 'accounting_line_not_posted'
    if invoice_no.startswith(INTERCOMPANY_PREFIXES):
        return 'intercompany_invoice'
    if invoice_no.startswith(LAPTOP_SALE_PREFIXES):
        return 'laptop_sale_invoice'
    if invoice_no in EXCLUDE_INV_NOS:
        return 'excluded_invoice'
    if (
        entity_id in EXCLUDE_ENTITIES
        or entity_name in EXCLUDE_ENTITY_NAMES
        or row.get('exclude_from_trade_ar') is True
    ):
        return 'excluded_entity'
    if any(fragment.casefold() in memo.casefold() for fragment in EXCLUDE_MEMO_CONTAINS):
        return 'laptop_sale_invoice'
    return 'eligible'


def _classify_invoices(rows, source_label):
    included = []
    manifest = []
    for source_row in rows:
        row = dict(source_row)
        reference_key = normalize_finance_reference(_invoice_reference(row))
        reason = _classification_reason(row)
        row['finance_reference_key'] = reference_key
        row['source_label'] = source_label
        (
            row['original_amount_transaction_currency'],
            row['original_amount'],
            row['currency'],
            row['fx_rate'],
        ) = _normalize_original_amount_inr(row)
        manifest_row = {
            'invoice_no': _invoice_reference(row),
            'finance_reference_key': reference_key,
            'source_label': source_label,
            'included': reason == 'eligible',
            'reason': reason,
            'currency': row['currency'],
            'fx_rate': row['fx_rate'],
            'original_amount_transaction_currency': row[
                'original_amount_transaction_currency'
            ],
            'original_amount_inr': row['original_amount'],
        }
        manifest.append(manifest_row)
        if reason == 'eligible':
            included.append(row)
    return included, manifest


def classify_native_invoices(rows):
    """Apply the GL-first native invoice population contract."""
    return _classify_invoices(rows, 'netsuite_native')


def classify_sap_invoices(rows):
    """Apply the same trade-debtor population rules to SAP carry-forward rows."""
    return _classify_invoices(rows, 'sap_carry_forward')


def select_receipts_in_window(receipts, start_date, end_date):
    """Select receipts on both inclusive calendar boundaries."""
    start = _as_date(start_date, 'receipt_start')
    end = _as_date(end_date, 'receipt_end')
    if end < start:
        raise ARContractError('receipt_end cannot be before receipt_start')

    selected = []
    for source_row in receipts:
        receipt_date = _as_date(source_row.get('receipt_date'), 'receipt_date')
        if start <= receipt_date <= end:
            row = dict(source_row)
            row['receipt_date'] = receipt_date
            row['amount'] = _as_decimal(row.get('amount'), 'receipt amount')
            row['source_label'] = row.get('source_label') or 'netsuite_receipt'
            selected.append(row)
    return selected


def replay_outstanding(invoices, movements, as_of_date):
    """Reconstruct invoice outstanding from dated, supported movements."""
    cutoff = _as_date(as_of_date, 'as_of_date')
    movements_by_reference = {}
    for source_movement in movements:
        movement = dict(source_movement)
        movement_type = str(movement.get('movement_type') or '').strip().lower()
        if movement_type not in ALLOWED_MOVEMENT_TYPES:
            raise ARContractError(
                f"unsupported movement_type {movement_type!r}; manual_addback and "
                "other undated adjustments are forbidden"
            )
        movement_date = _as_date(movement.get('movement_date'), 'movement_date')
        if movement_date > cutoff:
            continue
        reference_key = normalize_finance_reference(movement.get('invoice_ref'))
        amount = _as_decimal(movement.get('amount'), 'movement amount')
        if amount < 0:
            raise ARContractError('movement amount must be non-negative')
        movements_by_reference[reference_key] = (
            movements_by_reference.get(reference_key, Decimal('0.00')) + amount
        )

    replayed = []
    manifest = []
    for source_invoice in invoices:
        invoice = dict(source_invoice)
        reference_key = normalize_finance_reference(_invoice_reference(invoice))
        invoice_date = _as_date(invoice.get('invoice_date'), 'invoice_date')
        original_amount = _as_decimal(
            invoice.get('original_amount'), 'original_amount'
        )
        if original_amount < 0:
            raise ARContractError('original_amount must be non-negative')

        if invoice_date > cutoff:
            manifest.append({
                'invoice_no': _invoice_reference(invoice),
                'finance_reference_key': reference_key,
                'source_label': invoice.get('source_label'),
                'included': False,
                'reason': 'invoice_after_as_of',
                'original_amount': original_amount,
                'movements_through_as_of': Decimal('0.00'),
                'outstanding_as_of': Decimal('0.00'),
                'current_status_ignored': True,
            })
            continue

        applied = movements_by_reference.get(reference_key, Decimal('0.00'))
        outstanding = original_amount - applied
        if outstanding < 0:
            raise ARContractError(
                f"movements exceed original amount for {reference_key}"
            )
        invoice['finance_reference_key'] = reference_key
        invoice['invoice_date'] = invoice_date
        invoice['original_amount'] = original_amount
        invoice['outstanding_as_of'] = outstanding
        is_open = outstanding > 0
        if is_open:
            replayed.append(invoice)
        manifest.append({
            'invoice_no': _invoice_reference(invoice),
            'finance_reference_key': reference_key,
            'source_label': invoice.get('source_label'),
            'included': is_open,
            'reason': 'open_as_of' if is_open else 'settled_as_of',
            'original_amount': original_amount,
            'movements_through_as_of': applied,
            'outstanding_as_of': outstanding,
            'current_status_ignored': True,
        })
    return replayed, manifest


def _deduplicate_native_and_sap(native_rows, sap_rows):
    combined = list(native_rows)
    seen = {row['finance_reference_key'] for row in native_rows}
    manifest = []
    for row in sap_rows:
        reference_key = row['finance_reference_key']
        if reference_key in seen:
            manifest.append({
                'invoice_no': _invoice_reference(row),
                'finance_reference_key': reference_key,
                'source_label': row['source_label'],
                'included': False,
                'reason': 'duplicate_of_native',
            })
            continue
        seen.add(reference_key)
        combined.append(row)
    return combined, manifest


def _build_reconciliation(
    replay_manifest, open_invoices, netsuite_snapshot_id, sap_snapshot_id
):
    replay_population = [
        row for row in replay_manifest
        if row['reason'] in {'open_as_of', 'settled_as_of'}
    ]
    original_amount = sum(
        (row['original_amount'] for row in replay_population), Decimal('0.00')
    )
    movements = sum(
        (row['movements_through_as_of'] for row in replay_population),
        Decimal('0.00'),
    )
    outstanding = sum(
        (row['outstanding_as_of'] for row in replay_population), Decimal('0.00')
    )
    native_rows = [
        row for row in replay_population if row['source_label'] == 'netsuite_native'
    ]
    sap_rows = [
        row for row in replay_population if row['source_label'] == 'sap_carry_forward'
    ]
    return {
        'native_original_amount': sum(
            (row['original_amount'] for row in native_rows), Decimal('0.00')
        ),
        'sap_original_amount': sum(
            (row['original_amount'] for row in sap_rows), Decimal('0.00')
        ),
        'original_amount': original_amount,
        'movements_through_as_of': movements,
        'outstanding_as_of': outstanding,
        'difference': original_amount - movements - outstanding,
        'native_row_count': sum(
            row['source_label'] == 'netsuite_native' for row in open_invoices
        ),
        'sap_row_count': sum(
            row['source_label'] == 'sap_carry_forward' for row in open_invoices
        ),
        'open_row_count': len(open_invoices),
        'netsuite_snapshot_id': netsuite_snapshot_id,
        'sap_snapshot_id': sap_snapshot_id,
    }


def build_ar_contract(
    *, native_invoices, sap_invoices, movements, receipts, as_of_date,
    receipt_start, receipt_end, netsuite_snapshot_id, sap_snapshot_id
):
    """Build deterministic AR rows plus evidence needed by the golden harness."""
    if not netsuite_snapshot_id:
        raise NetSuiteSnapshotMissingError(
            'NetSuite frozen transaction-link snapshot id is required'
        )
    if not sap_invoices or not sap_snapshot_id:
        raise SAPCarryForwardMissingError(
            'SAP carry-forward rows and immutable snapshot id are required'
        )

    native_rows, native_manifest = classify_native_invoices(native_invoices)
    sap_rows, sap_manifest = classify_sap_invoices(sap_invoices)
    if not sap_rows:
        raise SAPCarryForwardMissingError(
            'SAP carry-forward contains no eligible trade-debtor rows'
        )
    combined, duplicate_manifest = _deduplicate_native_and_sap(
        native_rows, sap_rows
    )
    open_invoices, replay_manifest = replay_outstanding(
        combined, movements, as_of_date
    )
    selected_receipts = select_receipts_in_window(
        receipts, receipt_start, receipt_end
    )
    eligibility_exclusions = [
        row for row in native_manifest + sap_manifest if not row['included']
    ]
    manifest = eligibility_exclusions + duplicate_manifest + replay_manifest
    reconciliation = _build_reconciliation(
        replay_manifest, open_invoices, netsuite_snapshot_id, sap_snapshot_id
    )
    return {
        'open_invoices': open_invoices,
        'receipts': selected_receipts,
        'manifest': manifest,
        'reconciliation': reconciliation,
    }

