def get_aging_bucket(dpd):
    if dpd is None or dpd <= 0:
        return 'Not Due'
    elif dpd <= 7:
        return '0-7Days'
    elif dpd <= 15:
        return '8-15Days'
    elif dpd <= 30:
        return '16-30Days'
    elif dpd <= 60:
        return '31-60Days'
    elif dpd <= 90:
        return '61-90Days'
    elif dpd <= 120:
        return '91-120Days'
    elif dpd <= 180:
        return '121-180Days'
    else:
        return 'Above 181Days'

